BEGIN;
CREATE TABLE IF NOT EXISTS hollowgate_vtt.visual_assets(id uuid NOT NULL,campaign_id uuid NOT NULL REFERENCES hollowgate_vtt.campaigns(id) ON DELETE CASCADE,name text NOT NULL,asset_type text NOT NULL,source_mime text NOT NULL,source_data bytea NOT NULL,thumbnail_mime text NOT NULL,thumbnail_data bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id,campaign_id));
REVOKE ALL ON hollowgate_vtt.visual_assets FROM PUBLIC,hollowgate_api_runtime;
CREATE OR REPLACE FUNCTION hollowgate_vtt.visual_asset_owner_authorized(p_owner uuid,p_campaign uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM hollowgate_vtt.campaigns c JOIN hollowgate_auth.users u ON u.id=c.owner_id WHERE c.id=p_campaign AND c.owner_id=p_owner AND u.status='active' AND u.email_verified_at IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION hollowgate_vtt.list_owned_visual_assets(p_owner uuid,p_campaign uuid) RETURNS TABLE(id uuid,campaign_id uuid,name text,asset_type text,thumbnail_mime text,thumbnail_data bytea,created_at timestamptz) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT a.id,a.campaign_id,a.name,a.asset_type,a.thumbnail_mime,a.thumbnail_data,a.created_at FROM hollowgate_vtt.visual_assets a WHERE a.campaign_id=p_campaign AND hollowgate_vtt.visual_asset_owner_authorized(p_owner,p_campaign) ORDER BY a.name,a.id LIMIT 1000 $$;
CREATE OR REPLACE FUNCTION hollowgate_vtt.save_owned_visual_asset(p_owner uuid,p_campaign uuid,p_id uuid,p_name text,p_type text,p_source_mime text,p_source bytea,p_thumbnail_mime text,p_thumbnail bytea) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN IF NOT hollowgate_vtt.visual_asset_owner_authorized(p_owner,p_campaign) OR length(p_source)=0 OR length(p_source)>5242880 OR length(p_thumbnail)=0 OR length(p_thumbnail)>1048576 THEN RETURN NULL; END IF; INSERT INTO hollowgate_vtt.visual_assets(id,campaign_id,name,asset_type,source_mime,source_data,thumbnail_mime,thumbnail_data) VALUES(p_id,p_campaign,p_name,p_type,p_source_mime,p_source,p_thumbnail_mime,p_thumbnail) ON CONFLICT(id,campaign_id) DO UPDATE SET name=EXCLUDED.name,asset_type=EXCLUDED.asset_type,source_mime=EXCLUDED.source_mime,source_data=EXCLUDED.source_data,thumbnail_mime=EXCLUDED.thumbnail_mime,thumbnail_data=EXCLUDED.thumbnail_data; RETURN p_id; END $$;
CREATE OR REPLACE FUNCTION hollowgate_vtt.delete_owned_visual_asset(p_owner uuid,p_campaign uuid,p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ DECLARE v uuid; BEGIN IF NOT hollowgate_vtt.visual_asset_owner_authorized(p_owner,p_campaign) THEN RETURN NULL; END IF; DELETE FROM hollowgate_vtt.visual_assets WHERE id=p_id AND campaign_id=p_campaign RETURNING id INTO v; RETURN v; END $$;
REVOKE ALL ON FUNCTION hollowgate_vtt.visual_asset_owner_authorized(uuid,uuid),hollowgate_vtt.list_owned_visual_assets(uuid,uuid),hollowgate_vtt.save_owned_visual_asset(uuid,uuid,uuid,text,text,text,bytea,text,bytea),hollowgate_vtt.delete_owned_visual_asset(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION hollowgate_vtt.visual_asset_owner_authorized(uuid,uuid),hollowgate_vtt.list_owned_visual_assets(uuid,uuid),hollowgate_vtt.save_owned_visual_asset(uuid,uuid,uuid,text,text,text,bytea,text,bytea),hollowgate_vtt.delete_owned_visual_asset(uuid,uuid,uuid) TO hollowgate_api_runtime;
COMMIT;
